//! P6 differential fuzzer: drive BOTH brokers (upstream `ubusd` and the
//! in-tree `ubusd-rs`) with identical, seed-generated byte sequences.
//!
//! The generator is grammar-aware: it emits header-valid frames
//! (arbitrary type/seq/peer) with structurally-valid-then-corrupted TLV
//! payloads, the corruption position and kind driven entirely by the
//! seed. Seeds are literals or `$UBUS_ZERO_FUZZ_SEEDS`-derived — never
//! `SystemTime` — so every run is byte-for-byte reproducible; a failure
//! prints the seed and input hex for exact replay.
//! MONITOR now joins the parity grammar: rs answers inbound MONITOR frames
//! and implements the object-3 builtin.
//!
//! ## Two oracles, because rs is not a full libubus port
//!
//! `ubusd-rs` deliberately speaks only the subset of the ubus wire
//! protocol paths ubus-zero supports, making its own
//! reasonable choices on the long tail of malformed / stateless inputs.
//! Empirically it therefore does NOT match upstream byte-for-byte on
//! arbitrary fuzz frames (e.g. rs answers a garbage UNSUBSCRIBE with
//! STATUS(0) where upstream returns INVALID_ARGUMENT). Byte-for-byte
//! response parity IS the contract for the exercised protocol paths —
//! that is what `tests/ubusd_handshake.rs`'s matrix pins — but it is a
//! non-goal for arbitrary inputs, so this file does not gate on it.
//!
//! * **Robustness (always-on gate, [`differential_fuzz_bounded`]):** the
//!   achievable differential invariant is that NEITHER broker may crash,
//!   hang, or wedge on any input — after each case both must still serve
//!   a fresh client (HELLO + PING). A broker that dies where the other
//!   survives is a real bug.
//! * **Response parity (corpus + triage):** [`differential_fuzz_corpus`]
//!   replays checked-in `corpus/*.bin` regressions under the tolerant
//!   response oracle (rs may be stricter and close a peer where upstream
//!   returns an error status; any other response difference fails). The
//!   `#[ignore]`d [`differential_fuzz_parity_explore`] sweeps seeds under
//!   that same oracle to surface long-tail divergences for human triage:
//!   a divergence that is a genuine rs bug is fixed and captured as a
//!   corpus file; an accepted scope difference is left to the survey.
//!
//! Requires the upstream broker: without `.dep/bin/ubusd` this is a
//! visible skip (a hard panic under `UBUS_ZERO_COMPAT=require`).

use std::collections::BTreeMap;
use std::io::{Read, Write};
use std::os::unix::net::UnixStream;
use std::path::Path;
use std::time::{Duration, Instant};

use ubus::envelope::{EnvBuilder, UbusAttr};
use ubus::wire::{Codec, Frame, Header, MsgType, PROTO_VERSION};
use ubus_testkit::{
    canonicalize, skip, BrokerArm, CanonError, CanonEventKind, TapDirection, TapEvent,
    UbusdHarness, WireTap,
};

/// Default seed count for the always-on bounded run. Overridable with
/// `$UBUS_ZERO_FUZZ_SEEDS` (the soak test uses a larger literal count).
const BOUNDED_SEEDS: u64 = 256;

// ---- deterministic PRNG (SplitMix64) --------------------------------

struct Rng(u64);

impl Rng {
    fn new(seed: u64) -> Self {
        // Fold the seed so seed 0 doesn't degenerate to an all-zero
        // stream; SplitMix64 is otherwise fine from any state.
        Self(seed ^ 0xA0761D6478BD642F)
    }

    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// Uniform in `0..n` (n > 0).
    fn below(&mut self, n: u32) -> u32 {
        (self.next_u64() % u64::from(n)) as u32
    }

    fn byte(&mut self) -> u8 {
        self.next_u64() as u8
    }

    fn bool_1_in(&mut self, n: u32) -> bool {
        self.below(n) == 0
    }
}

// ---- grammar-aware frame generator ----------------------------------

const MSG_TYPES: [MsgType; 12] = [
    MsgType::Hello,
    MsgType::Status,
    MsgType::Data,
    MsgType::Ping,
    MsgType::Lookup,
    MsgType::Invoke,
    MsgType::AddObject,
    MsgType::RemoveObject,
    MsgType::Subscribe,
    MsgType::Unsubscribe,
    MsgType::Notify,
    MsgType::Monitor,
];

// The robustness/parity split existed while rs pre-dated MONITOR.
const MSG_TYPES_ROBUST: &[MsgType] = &MSG_TYPES;

/// A structurally valid frame: valid header (real version + a real
/// MsgType, arbitrary seq/peer) wrapping a well-formed envelope with a
/// handful of real attrs. `corrupt` mangles the encoded bytes afterward.
fn valid_frame(rng: &mut Rng, types: &[MsgType]) -> Vec<u8> {
    let ty = types[rng.below(types.len() as u32) as usize];
    let seq = rng.next_u64() as u16;
    // Bias peer toward small values (0, broker; 1, event object; a few
    // low object ids) so the event-bus and routing paths get exercised,
    // with an occasional arbitrary id.
    let peer = if rng.bool_1_in(3) {
        rng.next_u64() as u32
    } else {
        rng.below(6)
    };

    let mut env = EnvBuilder::new();
    for _ in 0..rng.below(4) {
        match rng.below(6) {
            0 => env.push_u32(UbusAttr::ObjId, rng.below(6)),
            1 => env.push_u32(UbusAttr::Target, rng.below(6)),
            2 => env.push_str(UbusAttr::Method, pick_method(rng)),
            3 => env.push_str(UbusAttr::ObjPath, "example.fuzz"),
            4 => env.push_i32(UbusAttr::Status, rng.next_u64() as i32),
            _ => env.push_data(&[]),
        }
    }
    let frame = Frame {
        hdr: Header {
            version: PROTO_VERSION,
            ty,
            seq,
            peer,
        },
        payload: env.finish(),
    };
    Codec::write_frame(&frame)
}

fn pick_method(rng: &mut Rng) -> &'static str {
    match rng.below(4) {
        0 => "register",
        1 => "send",
        2 => "ping",
        _ => "example.fuzz.event",
    }
}

/// Apply one seed-driven corruption to an encoded frame's TLV *payload*,
/// leaving the 8-byte header (version / type / seq / peer) intact — the
/// design scopes this to header-valid frames with corrupted payloads, so
/// unknown-MsgType handling (a deliberately stricter rs close path,
/// covered by `malformed_frame_closes_peer`) is out of bounds here. Kinds
/// span the payload framing surface: bit flips, truncation, length-field
/// mangling, and trailing junk — the classes that separate a lenient
/// decoder from a strict one.
fn corrupt(rng: &mut Rng, bytes: &mut Vec<u8>) {
    const HDR: usize = 8;
    // A header-only frame (empty payload) has nothing to corrupt but the
    // trailing-junk kind; keep it valid otherwise.
    match rng.below(5) {
        0 if bytes.len() > HDR => {
            // Flip one bit inside the payload.
            let i = HDR + rng.below((bytes.len() - HDR) as u32) as usize;
            bytes[i] ^= 1u8 << rng.below(8);
        }
        1 if bytes.len() > HDR => {
            // Truncate the payload (never into the header).
            let keep = HDR + rng.below((bytes.len() - HDR) as u32 + 1) as usize;
            bytes.truncate(keep);
        }
        2 if bytes.len() >= HDR + 4 => {
            // Mangle the 4-byte envelope length prefix (payload bytes
            // 8..12), the field that drives envelope sizing.
            let i = HDR + rng.below(4) as usize;
            bytes[i] = rng.byte();
        }
        3 if bytes.len() > HDR + 4 => {
            // Replace a byte inside the envelope body.
            let i = HDR + 4 + rng.below((bytes.len() - HDR - 4) as u32) as usize;
            bytes[i] = rng.byte();
        }
        _ => {
            // Append arbitrary trailing bytes (also the fallback when the
            // payload is too short for the chosen in-place corruption).
            for _ in 0..(1 + rng.below(16)) {
                bytes.push(rng.byte());
            }
        }
    }
}

/// One fuzz case: 1–2 connections, each a concatenation of 1–4
/// mostly-corrupted frames. Connections are driven in order.
fn gen_case_with(seed: u64, types: &[MsgType]) -> Vec<Vec<u8>> {
    let mut rng = Rng::new(seed);
    let conns = 1 + rng.below(2);
    (0..conns)
        .map(|_| {
            let frames = 1 + rng.below(4);
            let mut buf = Vec::new();
            for _ in 0..frames {
                let mut f = valid_frame(&mut rng, types);
                // ~75% of frames are corrupted; the rest stay valid so
                // sequences mix good and bad frames.
                if !rng.bool_1_in(4) {
                    corrupt(&mut rng, &mut f);
                }
                buf.extend_from_slice(&f);
            }
            buf
        })
        .collect()
}

/// Generate a parity-grammar case. Keep this seed mapping stable for the
/// corpus replayer and parity explorer.
fn gen_case(seed: u64) -> Vec<Vec<u8>> {
    gen_case_with(seed, &MSG_TYPES)
}

// ---- broker driver --------------------------------------------------

/// Drive one broker with `case` (per-connection byte blobs) behind a
/// tap, returning the raw broker→client tap events. `None` means the
/// broker binary isn't reachable (caller decides skip vs. panic).
///
/// Raw (un-canonicalized) so the oracle can number ids PER CONNECTION:
/// one connection's response count must not perturb another's canonical
/// id placeholders, which a single global bijection would allow when the
/// two brokers close different connections early.
fn drive(arm: BrokerArm, case: &[Vec<u8>]) -> Option<Vec<TapEvent>> {
    let started = match arm {
        BrokerArm::Upstream => UbusdHarness::start_upstream(),
        BrokerArm::Rs => UbusdHarness::start_rust(),
    };
    let harness = match started {
        Ok(Some(h)) => h,
        Ok(None) => return None,
        Err(e) => panic!("broker start ({arm:?}): {e:?}"),
    };
    let tap = WireTap::spawn(harness.socket_path())
        .unwrap_or_else(|e| panic!("spawn tap ({arm:?}): {e:?}"));
    let tap_path = tap.socket_path().to_owned();

    // Open each connection in order, drain the unsolicited HELLO, send
    // the fuzz bytes, then drain any response until the broker goes quiet
    // or closes the peer. Sequential opens keep HELLO arrival order (and
    // thus the canonical id numbering) deterministic across brokers.
    let mut conns = Vec::new();
    for blob in case {
        let mut c = UnixStream::connect(&tap_path).expect("connect through tap");
        c.set_read_timeout(Some(Duration::from_millis(50)))
            .expect("read timeout");
        c.set_write_timeout(Some(Duration::from_secs(2)))
            .expect("write timeout");
        drain_for(&mut c, Duration::from_millis(150));
        let _ = c.write_all(blob);
        conns.push(c);
    }
    for c in &mut conns {
        drain_for(c, Duration::from_millis(250));
    }
    drop(conns);

    // All fuzz connections are dropped, so the broker should close its
    // side of each and go quiescent. A timeout means a connection is
    // hung open — a real teardown race that would truncate the capture
    // nondeterministically — so surface it loudly rather than compare
    // half-captured event streams.
    if let Err(pending) = tap.wait_quiescent(Duration::from_secs(5)) {
        panic!(
            "differential_fuzz drive({arm:?}): tap did not reach quiescence within 5s — \
             teardown race. Still-open: {}",
            pending.join("; "),
        );
    }
    let events = tap.into_events();
    drop(harness);

    Some(
        events
            .into_iter()
            .filter(|e| e.dir == TapDirection::BrokerToClient)
            .collect(),
    )
}

/// Read and discard from `stream` until EOF or `quiet` elapses with no
/// bytes. The bytes still reach the tap; this just keeps the broker's
/// writes flowing and lets the peer-close (EOF) land.
fn drain_for(stream: &mut UnixStream, quiet: Duration) {
    let mut tmp = [0u8; 4096];
    let mut last = Instant::now();
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => return,
            Ok(_) => last = Instant::now(),
            Err(e)
                if e.kind() == std::io::ErrorKind::WouldBlock
                    || e.kind() == std::io::ErrorKind::TimedOut =>
            {
                if last.elapsed() >= quiet {
                    return;
                }
            }
            Err(e) if e.kind() == std::io::ErrorKind::ConnectionReset => return,
            Err(e) => panic!("drain read: {e:?}"),
        }
    }
}

// ---- oracle ---------------------------------------------------------

fn hex(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{b:02x}"));
    }
    s
}

fn render_case(case: &[Vec<u8>]) -> String {
    case.iter()
        .enumerate()
        .map(|(i, blob)| format!("  conn{i}: {}", hex(blob)))
        .collect::<Vec<_>>()
        .join("\n")
}

/// Canonicalize the broker→client events for a single connection, in
/// isolation (independent id numbering). Returns the response frames and
/// whether the broker closed the peer.
fn conn_responses(events: &[TapEvent], conn: usize) -> Result<(Vec<Frame>, bool), CanonError> {
    let scoped: Vec<TapEvent> = events.iter().filter(|e| e.conn == conn).cloned().collect();
    let transcript = canonicalize(&scoped)?;
    let frames = transcript
        .frames(conn, TapDirection::BrokerToClient)
        .to_vec();
    let closed = transcript.events().iter().any(|e| {
        e.conn == conn
            && e.dir == TapDirection::BrokerToClient
            && matches!(e.kind, CanonEventKind::Eof)
    });
    Ok((frames, closed))
}

/// Compare the brokers' responses under the contract that rs may be
/// STRICTER than upstream — it is allowed to close a peer where upstream
/// instead returns an error status (its documented malformed-input close
/// path; see `malformed_frame_closes_peer`). Per connection:
///
/// * rs's response frames must be a PREFIX of upstream's (any differing
///   response to an accepted frame is a real divergence);
/// * where rs emitted FEWER responses it must have closed the peer
///   (otherwise it silently swallowed a reply upstream sent);
/// * where the response counts match, liveness must agree (neither broker
///   is stricter for that exchange).
///
/// This tolerates only rs's known strict-close; a wrong response, an extra
/// response, or rs staying alive where upstream closed all fail.
struct Divergence {
    class: String,
    detail: String,
}

fn response_kind(frame: Option<&Frame>) -> String {
    match frame {
        None => "missing".to_owned(),
        Some(frame) if frame.hdr.ty == MsgType::Status => {
            match ubus::envelope::read_status(&frame.payload) {
                Ok(status) => format!("Status({status})"),
                Err(_) => "Status(malformed)".to_owned(),
            }
        }
        Some(frame) => format!("{:?}", frame.hdr.ty),
    }
}

fn compare(conns: usize, upstream: &[TapEvent], rs: &[TapEvent]) -> Option<Divergence> {
    for conn in 0..conns {
        let (up, up_closed, rsf, rs_closed) =
            match (conn_responses(upstream, conn), conn_responses(rs, conn)) {
                (Err(_), Err(_)) => {
                    // Identical corrupt input yields identical verbatim echoes;
                    // canon just cannot prove it for this uncomparable connection.
                    continue;
                }
                (Err(error), Ok(_)) => {
                    return Some(Divergence {
                        class: "uncanon-upstream".to_owned(),
                        detail: format!(
                            "conn{conn}: upstream response canonicalization failed: {error}"
                        ),
                    });
                }
                (Ok(_), Err(error)) => {
                    return Some(Divergence {
                        class: "uncanon-rs".to_owned(),
                        detail: format!("conn{conn}: rs response canonicalization failed: {error}"),
                    });
                }
                (Ok((up, up_closed)), Ok((rsf, rs_closed))) => (up, up_closed, rsf, rs_closed),
            };
        if rsf.len() > up.len() || rsf != up[..rsf.len().min(up.len())] {
            let at = (0..rsf.len().min(up.len()))
                .find(|&i| rsf[i] != up[i])
                .unwrap_or(up.len().min(rsf.len()));
            return Some(Divergence {
                class: format!(
                    "resp-mismatch up={} rs={}",
                    response_kind(up.get(at)),
                    response_kind(rsf.get(at)),
                ),
                detail: format!(
                    "conn{conn}: rs responses are not a prefix of upstream's\n  first differing index {at}\n  upstream ({} frame(s)): {:?}\n  rs ({} frame(s)):       {:?}",
                    up.len(),
                    up.get(at).map(render_frame),
                    rsf.len(),
                    rsf.get(at).map(render_frame),
                ),
            });
        }
        if rsf.len() == up.len() {
            if rs_closed != up_closed {
                return Some(Divergence {
                    class: format!("liveness up_closed={up_closed} rs_closed={rs_closed}"),
                    detail: format!(
                        "conn{conn}: identical responses but liveness differs (upstream closed={up_closed}, rs closed={rs_closed})"
                    ),
                });
            }
        } else if !rs_closed {
            return Some(Divergence {
                class: "rs-missing-response not-closed".to_owned(),
                detail: format!(
                    "conn{conn}: rs emitted {} of upstream's {} responses but did not close the peer",
                    rsf.len(),
                    up.len()
                ),
            });
        }
    }
    None
}

fn render_frame(f: &Frame) -> String {
    format!("hdr={:?} payload={}", f.hdr, hex(&f.payload))
}

/// Triage helper: for a single-connection case, report whether the
/// tolerant oracle accepts it AND rs strict-closed where upstream instead
/// returned response frames. Such cases are the corpus-eligible drift
/// guards (the tolerant oracle stays green precisely because rs is allowed
/// to be stricter than upstream). `None` when a broker is unreachable.
fn strict_close_case(case: &[Vec<u8>]) -> Option<bool> {
    let upstream = drive(BrokerArm::Upstream, case)?;
    let rs = drive(BrokerArm::Rs, case)?;
    if compare(case.len(), &upstream, &rs).is_some() {
        return Some(false);
    }
    // Tolerant oracle passed. It is a strict-close (rather than an
    // identical exchange) iff some conn had rs close with fewer frames
    // than upstream's non-empty response.
    for conn in 0..case.len() {
        let (Ok((up, _)), Ok((rsf, rs_closed))) =
            (conn_responses(&upstream, conn), conn_responses(&rs, conn))
        else {
            continue;
        };
        if rs_closed && rsf.len() < up.len() && !up.is_empty() {
            return Some(true);
        }
    }
    Some(false)
}

/// Run one case against both brokers and return any response divergence.
/// `None` also preserves the visible skip when either broker is unreachable.
fn case_divergence(test: &str, _label: &str, case: &[Vec<u8>]) -> Option<Divergence> {
    let Some(upstream) = drive(BrokerArm::Upstream, case) else {
        skip::or_skip(test, "upstream broker not reachable");
        return None;
    };
    let Some(rs) = drive(BrokerArm::Rs, case) else {
        skip::or_skip(test, "rs broker not reachable");
        return None;
    };
    compare(case.len(), &upstream, &rs)
}

/// Run one case against both brokers and assert the contract in
/// [`compare`]. `label` names the case (seed number or corpus filename)
/// so a failure is reproducible verbatim.
fn run_case(test: &str, label: &str, case: &[Vec<u8>]) {
    if let Some(diff) = case_divergence(test, label, case) {
        panic!(
            "{test}: {label} DIVERGENCE between upstream and rs\ninput:\n{}\n{}",
            render_case(case),
            diff.detail,
        );
    }
}

// ---- robustness oracle ----------------------------------------------

/// Feed `case` (per-connection byte blobs) to the broker at `sock` on
/// throwaway connections. Errors are swallowed: a broker that closes a
/// peer mid-write is exercising exactly the path under test.
fn drive_input(sock: &Path, case: &[Vec<u8>]) {
    for blob in case {
        if let Ok(mut c) = UnixStream::connect(sock) {
            c.set_write_timeout(Some(Duration::from_secs(2))).ok();
            // Deliver the bytes and drop; the broker reads them (then sees
            // EOF) on its own poll loop. The periodic fresh-PING check is
            // what proves survival, so there is nothing to read here.
            let _ = c.write_all(blob);
        }
    }
}

/// Robustness sweep: drive every seed's input into ONE upstream and ONE
/// rs broker instance (cumulative stress), asserting both still answer a
/// fresh PING every `CHECK_EVERY` seeds and at the end. A broker that
/// crashes, hangs, or wedges — where the other survives, or at all — is a
/// real bug. Reusing a single broker per arm keeps the sweep in the
/// seconds range (2 spawns, not two-per-seed).
fn robustness_sweep(test: &str, seeds: u64) {
    const CHECK_EVERY: u64 = 16;
    let up = match UbusdHarness::start_upstream() {
        Ok(Some(h)) => h,
        Ok(None) => {
            skip::or_skip(test, "upstream broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: upstream start: {e:?}"),
    };
    let rs = match UbusdHarness::start_rust() {
        Ok(Some(h)) => h,
        Ok(None) => {
            skip::or_skip(test, "rs broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: rs start: {e:?}"),
    };
    let up_sock = up.socket_path().to_owned();
    let rs_sock = rs.socket_path().to_owned();
    for seed in 0..seeds {
        let case = gen_case_with(seed, MSG_TYPES_ROBUST);
        drive_input(&up_sock, &case);
        drive_input(&rs_sock, &case);
        if seed % CHECK_EVERY == CHECK_EVERY - 1 || seed + 1 == seeds {
            let up_alive = fresh_ping_answered(&up_sock);
            let rs_alive = fresh_ping_answered(&rs_sock);
            assert!(
                up_alive && rs_alive,
                "{test}: broker crashed/wedged by seed {seed} (upstream alive={up_alive}, rs alive={rs_alive})"
            );
        }
    }
}

/// A fresh client handshakes (unsolicited HELLO) and its PING is answered
/// with a terminating STATUS. False if the broker is dead/wedged.
fn fresh_ping_answered(sock: &Path) -> bool {
    let Ok(mut c) = UnixStream::connect(sock) else {
        return false;
    };
    c.set_read_timeout(Some(Duration::from_millis(200))).ok();
    c.set_write_timeout(Some(Duration::from_secs(1))).ok();
    let mut buf = Vec::new();
    if read_frame_within(&mut c, &mut buf, Duration::from_secs(2), |f| {
        f.hdr.ty == MsgType::Hello
    })
    .is_none()
    {
        return false;
    }
    let ping = Frame {
        hdr: Header {
            version: PROTO_VERSION,
            ty: MsgType::Ping,
            seq: 0x7abc,
            peer: 0,
        },
        payload: EnvBuilder::new().finish(),
    };
    if c.write_all(&Codec::write_frame(&ping)).is_err() {
        return false;
    }
    read_frame_within(&mut c, &mut buf, Duration::from_secs(2), |f| {
        f.hdr.seq == 0x7abc && f.hdr.ty == MsgType::Status
    })
    .is_some()
}

/// Buffered streaming read of a raw `UnixStream` until a frame matching
/// `pred` decodes, or the deadline elapses (returns `None`).
fn read_frame_within(
    stream: &mut UnixStream,
    buf: &mut Vec<u8>,
    timeout: Duration,
    pred: impl Fn(&Frame) -> bool,
) -> Option<Frame> {
    let deadline = Instant::now() + timeout;
    loop {
        while let Ok((frame, consumed)) = Codec::read_frame(buf) {
            buf.drain(..consumed);
            if pred(&frame) {
                return Some(frame);
            }
        }
        if Instant::now() >= deadline {
            return None;
        }
        let mut tmp = [0u8; 1024];
        match stream.read(&mut tmp) {
            Ok(0) => return None,
            Ok(n) => buf.extend_from_slice(&tmp[..n]),
            Err(e)
                if e.kind() == std::io::ErrorKind::WouldBlock
                    || e.kind() == std::io::ErrorKind::TimedOut => {}
            Err(_) => return None,
        }
    }
}

// ---- tests ----------------------------------------------------------

fn seed_count() -> u64 {
    std::env::var("UBUS_ZERO_FUZZ_SEEDS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(BOUNDED_SEEDS)
}

/// Always-on gate: neither broker may crash, hang, or wedge on any
/// seed-generated input. Byte-for-byte response parity over arbitrary
/// input is a non-goal for rs (see the module doc); robustness is the
/// achievable differential invariant.
#[test]
fn differential_fuzz_bounded() {
    let test = "differential_fuzz differential_fuzz_bounded";
    robustness_sweep(test, seed_count());
}

/// Robustness soak for manual/CI-nightly use: a much larger seed sweep.
/// `#[ignore]` so the default `cargo test` stays in the seconds range.
#[test]
#[ignore = "soak: large robustness seed sweep, run explicitly"]
fn differential_fuzz_long() {
    let test = "differential_fuzz differential_fuzz_long";
    let count = std::env::var("UBUS_ZERO_FUZZ_SEEDS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(8192);
    robustness_sweep(test, count);
}

/// Replay every checked-in regression under the tolerant response oracle
/// ([`compare`]): each `corpus/*.bin` is the raw byte blob for one
/// single-connection case whose response divergence was triaged as a real
/// rs bug and fixed — they must stay green (the fix landed with the case).
#[test]
fn differential_fuzz_corpus() {
    let test = "differential_fuzz differential_fuzz_corpus";
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("corpus");
    let mut entries: Vec<_> = match std::fs::read_dir(&dir) {
        Ok(rd) => rd
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| p.extension().is_some_and(|x| x == "bin"))
            .collect(),
        Err(_) => Vec::new(),
    };
    entries.sort();
    if entries.is_empty() {
        // No regressions recorded yet — nothing to replay, but the test
        // is a live harness the moment the first corpus file lands.
        return;
    }
    match UbusdHarness::start_upstream() {
        Ok(Some(_)) => {}
        Ok(None) => {
            skip::or_skip(test, "upstream broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: upstream probe: {e:?}"),
    }
    for path in entries {
        let bytes = std::fs::read(&path).expect("read corpus file");
        let label = path.file_name().unwrap().to_string_lossy().into_owned();
        run_case(test, &label, &[bytes]);
    }
}

/// Triage explorer (`#[ignore]`): survey parity-grammar seeds under the
/// tolerant response oracle, grouping every divergence class for human
/// triage. Run this to hunt real rs response bugs; a genuine one is fixed
/// in rs and captured as a `corpus/*.bin` file, an accepted scope difference
/// is left alone. NOT a gate — rs is not a full libubus port (see the module
/// doc).
#[test]
#[ignore = "triage: hunts long-tail response divergences, not a gate"]
fn differential_fuzz_parity_explore() {
    let test = "differential_fuzz differential_fuzz_parity_explore";
    match UbusdHarness::start_upstream() {
        Ok(Some(_)) => {}
        Ok(None) => {
            skip::or_skip(test, "upstream broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: upstream probe: {e:?}"),
    }
    let total = seed_count();
    let mut divergences: BTreeMap<String, (u64, u64)> = BTreeMap::new();
    let mut divergent = 0;
    for seed in 0..total {
        if let Some(diff) = case_divergence(test, &format!("seed {seed}"), &gen_case(seed)) {
            println!("seed {seed}: {}", diff.class);
            let entry = divergences.entry(diff.class).or_insert((0, seed));
            entry.0 += 1;
            divergent += 1;
        }
    }
    let mut summary: Vec<_> = divergences.into_iter().collect();
    summary.sort_by(|(class_a, (count_a, _)), (class_b, (count_b, _))| {
        count_b.cmp(count_a).then_with(|| class_a.cmp(class_b))
    });
    for (class, (count, exemplar)) in summary {
        println!("{count}× {class} (exemplar seed {exemplar})");
    }
    println!("explored {total} seeds, {divergent} divergent");
}

/// Triage one or more explore seeds in depth: prints each seed's exact
/// per-connection input hex (the corpus-file payload for single-connection
/// cases) plus the full divergence detail from the tolerant oracle. Feed
/// it the exemplar seeds from a `differential_fuzz_parity_explore` summary:
///
/// ```text
/// UBUS_ZERO_FUZZ_TRIAGE_SEEDS=6,11,46 cargo test -p ubus-testkit \
///   --test differential_fuzz -- --ignored differential_fuzz_triage_seeds \
///   --nocapture
/// ```
#[test]
#[ignore = "triage: per-seed deep dive, driven by UBUS_ZERO_FUZZ_TRIAGE_SEEDS"]
fn differential_fuzz_triage_seeds() {
    let test = "differential_fuzz differential_fuzz_triage_seeds";
    let Ok(raw) = std::env::var("UBUS_ZERO_FUZZ_TRIAGE_SEEDS") else {
        println!("{test}: UBUS_ZERO_FUZZ_TRIAGE_SEEDS not set; nothing to triage");
        return;
    };
    match UbusdHarness::start_upstream() {
        Ok(Some(_)) => {}
        Ok(None) => {
            skip::or_skip(test, "upstream broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: upstream probe: {e:?}"),
    }
    for seed in raw.split(',').filter_map(|s| s.trim().parse::<u64>().ok()) {
        let case = gen_case(seed);
        println!("==== seed {seed} ({} conn(s)) ====", case.len());
        println!("{}", render_case(&case));
        match case_divergence(test, &format!("seed {seed}"), &case) {
            Some(diff) => println!("class: {}\n{}", diff.class, diff.detail),
            None => println!("no divergence"),
        }
    }
}

/// Mine single-connection, tolerant-oracle-green seeds where rs strict-closes
/// while upstream returns response frames — the corpus-eligible drift guards
/// (see `differential_fuzz_corpus`). Prints `seed <n>: strict-close` lines so
/// the exemplars can be captured as `corpus/*.bin` files.
#[test]
#[ignore = "triage: mine rs strict-close seeds for the corpus"]
fn differential_fuzz_strict_close_scan() {
    let test = "differential_fuzz differential_fuzz_strict_close_scan";
    match UbusdHarness::start_upstream() {
        Ok(Some(_)) => {}
        Ok(None) => {
            skip::or_skip(test, "upstream broker not reachable");
            return;
        }
        Err(e) => panic!("{test}: upstream probe: {e:?}"),
    }
    let mut found = 0;
    for seed in 0..seed_count() {
        let case = gen_case(seed);
        if case.len() != 1 {
            continue;
        }
        if strict_close_case(&case) == Some(true) {
            println!("seed {seed}: strict-close");
            found += 1;
        }
    }
    println!("mined {found} single-connection strict-close seed(s)");
}
